package com.dataengine.governance.service;
import com.dataengine.governance.domain.*; import com.dataengine.governance.repository.LineageEdgeRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class LineageGovernanceService {private final LineageEdgeRepository edges;public LineageGovernanceService(LineageEdgeRepository e){edges=e;}public LineageEdge confirm(UUID id,String actor,String reason){LineageEdge edge=require(id);if(edge.getStatus()!=LineageStatus.CANDIDATE)throw new GovernanceException("只有候选血缘可以确认");edge.confirm(actor,requireReason(reason));return edges.save(edge);}public LineageEdge reject(UUID id,String actor,String reason){LineageEdge edge=require(id);if(edge.getStatus()!=LineageStatus.CANDIDATE)throw new GovernanceException("只有候选血缘可以驳回");edge.reject(actor,requireReason(reason));return edges.save(edge);}private LineageEdge require(UUID id){return edges.findById(id).orElseThrow(()->new GovernanceException("血缘关系不存在"));}private String requireReason(String reason){if(reason==null||reason.isBlank())throw new GovernanceException("血缘处置必须填写原因");return reason.trim();}}
